function getUrlParams(url) {
    let params = new URL(url).searchParams;
    let paramObj = {};
    params.forEach((value, key) => {
        paramObj[key] = value;
    });
    return paramObj;
}

// Function to update parameters while keeping ms and initialms
function updateUrl(baseUrl, newPcode, newLpcode) {
    let currentParams = getUrlParams(window.location.href); // Get current URL parameters

    // Preserve ms and initialms, update pcode and lpcode
    let updatedParams = new URLSearchParams({
        ms: currentParams.ms || "", 
        initialms: currentParams.initialms || "",
        pcode: newPcode, 
        lpcode: newLpcode
    });

    return `${baseUrl}?${updatedParams.toString()}`;
}

// Example: Update the links dynamically
document.addEventListener("DOMContentLoaded", function () {
      let tab1 = document.getElementById("onetime1"); // Adjust ID for your second tab
  let tab2 = document.getElementById("monthly"); // Adjust ID for your second tab
    if (tab1) {
        tab1.href = updateUrl("https://secure.aspca.org/donate/ps-gn-sl-202509-p2", "WPSDEF2", "WPSDEF1");
    }
    if (tab2) {
        tab2.href = updateUrl("https://secure.aspca.org/donate/ps-gn-sl-202509-p1", "WPSDEF1", "WPSDEF2");
    }
});
