var variantTag = '-c'; 

document.addEventListener('DOMContentLoaded', function () {
  document.querySelectorAll('a[href*="/donate/"]').forEach(function (link) {
    try {
      var url = new URL(link.href);

      // Modify 'ms' parameter if it exists
      if (url.searchParams.has('ms')) {
        var currentMs = url.searchParams.get('ms');
        url.searchParams.set('ms', currentMs + variantTag);
      }

      // Modify 'initialms' parameter if it exists
      if (url.searchParams.has('initialms')) {
        var currentInitialMs = url.searchParams.get('initialms');
        url.searchParams.set('initialms', currentInitialMs + variantTag);
      }

      link.href = url.toString();
    } catch (e) {
      console.warn('Invalid URL:', link.href);
    }
  });
});
