function getUrlParams(url) {
    let params = new URL(url).searchParams;
    let paramObj = {};
    params.forEach((value, key) => {
        paramObj[key] = value;
    });
    return paramObj;
}

// Function to update parameters while keeping ms and initialms
function updateUrl(baseUrl, newPcode, newLpcode) {
    let currentParams = getUrlParams(window.location.href); // Get current URL parameters

    // Preserve ms and initialms, update pcode and lpcode
    let updatedParams = new URLSearchParams({
        ms: currentParams.ms || "", 
        initialms: currentParams.initialms || "",
        pcode: newPcode, 
        lpcode: newLpcode
    });

    return `${baseUrl}?${updatedParams.toString()}`;
}

